  function openArticle(button,name,article){close();button.classList.add('is-active');button.setAttribute('aria-pressed','true');shade=document.createElement('div');shade.className='kena-article-backdrop scripture-wiki-backdrop';reader=document.createElement('section');reader.className='kena-article-reader scripture-wiki-reader itihasa-human-reader';reader.setAttribute('role','dialog');reader.setAttribute('aria-modal','true');reader.setAttribute('aria-label',`${name} article`);reader.innerHTML=`<header class="kena-article-head"><div><span class="eyebrow">Itihāsa encyclopedia</span><h1>${esc(article.title)}</h1></div><button class="kena-article-close" type="button" aria-label="Close">×</button></header><div class="kena-article-scroll"><article class="scripture-wiki-article itihasa-human-article"><aside class="kena-infobox"><div class="kena-infobox-title">${esc(article.title)}</div><div class="kena-info-row"><b>Sanskrit</b><span>${esc(article.sanskrit)}</span></div><div class="kena-info-row"><b>Traditional author</b><span>${esc(article.author)}</span></div><div class="kena-info-row"><b>Language</b><span>${esc(article.language)}</span></div><div class="kena-info-row"><b>Extent</b><span>${esc(article.extent)}</span></div><div class="kena-info-row"><b>Date</b><span>${esc(article.date)}</span></div></aside>${article.body()}${notesHtml(article)}</article></div>`;document.body.append(shade,reader);document.documentElement.classList.add('kena-article-open');reader.addEventListener('click',e=>{const cite=e.target.closest('.itihasa-cite button,.itihasa-note-link');if(cite){e.preventDefault();e.stopPropagation();showSource(article,Number(cite.dataset.note));return;}if(e.target.closest('.kena-article-close'))close();});shade.addEventListener('click',close);return true;}

  if(!document.getElementById('itihasa-scholarly-v3-style')){const style=document.createElement('style');style.id='itihasa-scholarly-v3-style';style.textContent=`.itihasa-human-article .kena-lead p{max-width:790px;font-size:16.6px;line-height:1.78}.itihasa-human-article .kena-section>p{max-width:930px;font-size:16px;line-height:1.78}.itihasa-human-article .kena-section h3{max-width:930px;margin:28px 0 10px!important;font-size:21px!important}.itihasa-human-article .kena-section h3+ p{margin-top:0}.itihasa-cite{vertical-align:super;margin-left:1px}.itihasa-cite button,.itihasa-note-link{border:0;background:transparent;color:#36c;padding:0 1px;font:600 10.5px/1 Arial,sans-serif;cursor:pointer}.itihasa-cite button:hover,.itihasa-note-link:hover{text-decoration:underline}.itihasa-source-card{position:fixed;z-index:13050;right:22px;bottom:22px;width:min(440px,calc(100vw - 32px));padding:17px 18px 16px;border:1px solid #a2a9b1;border-radius:4px;background:#fff;box-shadow:0 12px 38px rgba(0,0,0,.24);color:#202122;font-family:Arial,sans-serif}.itihasa-source-card strong{display:block;padding-right:30px;font-size:15px;line-height:1.35}.itihasa-source-card p{margin:8px 0 10px;font-size:13.5px;line-height:1.55}.itihasa-source-card a{color:#36c;font-size:13px}.itihasa-source-num{margin-bottom:5px;color:#54595d;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em}.itihasa-source-close{position:absolute;right:8px;top:7px;border:0;background:transparent;font-size:23px;cursor:pointer;color:#54595d}.itihasa-human-article .kena-references li{margin-bottom:13px}.itihasa-human-article .kena-references li span{color:#54595d;font-size:12.8px}.itihasa-toc{margin-bottom:36px}@media(max-width:700px){.itihasa-source-card{right:12px;bottom:12px;width:calc(100vw - 24px)}.itihasa-human-article .kena-section>p{font-size:15.8px;line-height:1.74}.itihasa-human-article .kena-lead p{font-size:16px;line-height:1.75}}`;document.head.appendChild(style);}

